                {screen === 'sharepoint_summer_extracted' && !isChatLoading && pendingSummerSkills.length === 0 && (
                  <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} style={{ display: 'flex', alignItems: 'center', gap: '12px', justifyContent: 'center', marginTop: '24px', padding: '16px', backgroundColor: 'var(--nu-surface)', borderRadius: 'var(--radius-card)' }}>
                    <span style={{ fontSize: '14px', fontWeight: 600, color: 'var(--nu-text-secondary)' }}>View Advisor Dashboard (Demo Mode)</span>
                    <div 
