          <Card key={i} style={{ borderTop: '4px solid var(--nu-red)' }}>
            <div style={{ fontSize: '14px', fontWeight: 600, color: 'var(--nu-text-secondary)', textTransform: 'uppercase', letterSpacing: '0.5px' }}>
